/*!
 * Motion.dev Web Animations Runtime (CSP-safe local bundle for WealthFlow)
 * Exposes window.Motion = { animate, stagger, spring, inView, press, wave, waveGroup, spawnClickWave }
 * powered by Element.animate (WAAPI).
 */
(function (global) {
  "use strict";

  const DEFAULT_EASE = "cubic-bezier(0.16, 1, 0.3, 1)";
  const DEFAULT_DURATION = 0.50;
  const TRANSFORM_KEYS = new Set(["x", "y", "scale", "rotate", "transform"]);

  const REDUCED_MOTION = () =>
    typeof window !== "undefined" &&
    window.matchMedia &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  function resolveElements(target) {
    if (!target) return [];
    if (typeof target === "string") return Array.from(document.querySelectorAll(target));
    if (target instanceof Element) return [target];
    if (Array.isArray(target) || target instanceof NodeList || target instanceof HTMLCollection) {
      return Array.from(target).filter((el) => el instanceof Element);
    }
    return [];
  }

  function buildTransform(x, y, scale, rotate) {
    const parts = [];
    if (x !== undefined) parts.push(`translateX(${typeof x === "number" ? `${x}px` : x})`);
    if (y !== undefined) parts.push(`translateY(${typeof y === "number" ? `${y}px` : y})`);
    if (scale !== undefined) parts.push(`scale(${scale})`);
    if (rotate !== undefined) parts.push(`rotate(${typeof rotate === "number" ? `${rotate}deg` : rotate})`);
    return parts.join(" ");
  }

  function toKeyframes(kf) {
    const source = kf || {};
    const keys = Object.keys(source);
    let length = 1;

    for (const key of keys) {
      if (Array.isArray(source[key]) && source[key].length > length) {
        length = source[key].length;
      }
    }

    const frames = [];
    for (let i = 0; i < length; i++) {
      const frame = {};
      const valAt = (k) => {
        const v = source[k];
        if (v === undefined) return undefined;
        return Array.isArray(v) ? v[Math.min(i, v.length - 1)] : v;
      };

      for (const key of keys) {
        if (TRANSFORM_KEYS.has(key)) continue;
        const val = valAt(key);
        if (val !== undefined) frame[key] = val;
      }

      const x = valAt("x");
      const y = valAt("y");
      const scale = valAt("scale");
      const rotate = valAt("rotate");
      const rawTf = valAt("transform");

      if (rawTf !== undefined) {
        frame.transform = rawTf;
      } else {
        const tf = buildTransform(x, y, scale, rotate);
        if (tf) frame.transform = tf;
      }

      if (Object.keys(frame).length > 0) {
        frames.push(frame);
      }
    }

    if (frames.length === 1) {
      frames.unshift({});
    }
    return frames;
  }

  function spring(opts = {}) {
    const stiffness = Number(opts.stiffness || 200);
    const damping = Number(opts.damping || 26);
    const duration = Math.min(0.72, Math.max(0.48, (damping / Math.sqrt(Math.max(1, stiffness))) * 0.34));
    return {
      duration,
      easing: DEFAULT_EASE
    };
  }

  function stagger(step = 0.045, opts = {}) {
    const start = Number(opts.start || 0);
    const stepNum = Number(step || 0.045);
    const fromOpt = opts.from;

    return (index, total = 1) => {
      if (fromOpt === undefined || fromOpt === null || fromOpt === "first") {
        return start + index * stepNum;
      }
      if (fromOpt === "last") {
        return start + Math.max(0, total - 1 - index) * stepNum;
      }
      const origin = fromOpt === "center" ? (total - 1) / 2 : Number(fromOpt);
      const dist = Number.isFinite(origin) ? Math.abs(index - origin) : index;
      return start + dist * stepNum;
    };
  }

  function resolveEasing(easingOpt) {
    if (easingOpt && typeof easingOpt === "object" && !Array.isArray(easingOpt) && easingOpt.easing) {
      return easingOpt.easing;
    }
    if (Array.isArray(easingOpt)) {
      return `cubic-bezier(${easingOpt.join(",")})`;
    }
    return easingOpt || DEFAULT_EASE;
  }

  function animate(target, keyframes, options = {}) {
    const els = resolveElements(target);
    if (!els.length) {
      return { finished: Promise.resolve(), cancel: function () {} };
    }

    if (REDUCED_MOTION() || typeof els[0].animate !== "function") {
      return { finished: Promise.resolve(), cancel: function () {} };
    }

    const kf = toKeyframes(keyframes);
    const resolvedEasing = resolveEasing(options.easing || options.ease);

    const baseDurationSec =
      options.duration !== undefined
        ? Number(options.duration)
        : options.easing && !Array.isArray(options.easing) && options.easing.duration
        ? Number(options.easing.duration)
        : DEFAULT_DURATION;

    const anims = els
      .map((el, idx) => {
        const delaySec =
          typeof options.delay === "function" ? Number(options.delay(idx, els.length)) : Number(options.delay || 0);

        try {
          return el.animate(kf, {
            duration: Math.max(10, Math.round(baseDurationSec * 1000)),
            delay: Math.max(0, Math.round(delaySec * 1000)),
            easing: resolvedEasing,
            fill: options.fill || "both"
          });
        } catch (_e) {
          return null;
        }
      })
      .filter(Boolean);

    const finished = Promise.all(anims.map((a) => a.finished.catch(() => {})));
    if (options.clearOnFinish) {
      finished.then(() => {
        anims.forEach((a) => {
          try {
            a.cancel();
          } catch (_) {}
        });
      });
    }

    return {
      finished,
      cancel: () =>
        anims.forEach((a) => {
          try {
            a.cancel();
          } catch (_) {}
        })
    };
  }

  function inView(target, callback, options = {}) {
    const els = resolveElements(target);
    if (!els.length || typeof callback !== "function") {
      return () => {};
    }

    if (typeof IntersectionObserver !== "function" || REDUCED_MOTION()) {
      els.forEach((el) => callback({ target: el, isIntersecting: true }));
      return () => {};
    }

    const once = options.once !== false;
    const threshold = options.amount !== undefined ? options.amount : (options.threshold !== undefined ? options.threshold : 0.12);
    const rootMargin = options.margin || options.rootMargin || "0px";

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            callback(entry);
            if (once) observer.unobserve(entry.target);
          }
        });
      },
      { threshold, rootMargin }
    );

    els.forEach((el) => observer.observe(el));
    return () => observer.disconnect();
  }

  function press(target, options = {}) {
    const els = resolveElements(target);
    if (!els.length) return () => {};

    const downScale = Number(options.scale || 0.95);
    const dur = Number(options.duration || 0.42);
    const ease = options.easing || [0.16, 1, 0.3, 1];
    const cleanups = [];

    els.forEach((el) => {
      const onDown = () => {
        if (el.disabled) return;
        if (el.__wfPressHelperAnim) el.__wfPressHelperAnim.cancel();
        el.__wfPressHelperAnim = animate(el, { scale: [1, downScale] }, { duration: Math.min(0.24, dur * 0.5), easing: ease });
      };
      const onUp = () => {
        if (el.__wfPressHelperAnim) el.__wfPressHelperAnim.cancel();
        el.__wfPressHelperAnim = animate(
          el,
          { scale: [downScale, 1.02, 1] },
          { duration: dur, easing: ease, clearOnFinish: true }
        );
      };
      el.addEventListener("pointerdown", onDown);
      el.addEventListener("pointerup", onUp);
      el.addEventListener("pointercancel", onUp);
      cleanups.push(() => {
        el.removeEventListener("pointerdown", onDown);
        el.removeEventListener("pointerup", onUp);
        el.removeEventListener("pointercancel", onUp);
      });
    });

    return () => cleanups.forEach((fn) => fn());
  }

  function wave(target, options = {}) {
    const els = resolveElements(target);
    if (!els.length) {
      return { finished: Promise.resolve(), cancel: function () {} };
    }

    return animate(
      els,
      {
        opacity: options.opacity || [0.86, 1],
        y: options.y || [7, -1.5, 0]
      },
      {
        duration: options.duration !== undefined ? Number(options.duration) : 0.54,
        delay: stagger(options.step || 0.045, { start: options.start || 0, from: options.from }),
        easing: options.easing || [0.16, 1, 0.3, 1],
        clearOnFinish: true
      }
    );
  }

  function waveGroup(buttons, activeBtn, options = {}) {
    const list = resolveElements(buttons);
    if (!list.length) return;

    const now = Date.now();
    if (activeBtn && Number(activeBtn.dataset.wfWavedAt || 0) > now - 220) {
      return;
    }
    if (activeBtn) {
      activeBtn.dataset.wfWavedAt = String(now);
    }

    const activeIdx = activeBtn ? list.indexOf(activeBtn) : -1;
    const step = Number(options.step || 0.045);

    list.forEach((el, idx) => {
      if (!el || el.disabled) return;
      if (el.__wfBtnAnim) el.__wfBtnAnim.cancel();

      const delay = activeIdx >= 0 ? Math.abs(idx - activeIdx) * step : idx * step;
      if (idx === activeIdx) {
        el.__wfBtnAnim = animate(
          el,
          { y: [0, -2.5, 0], scale: [0.96, 1.03, 1] },
          { duration: 0.50, delay, easing: [0.16, 1, 0.3, 1], clearOnFinish: true }
        );
      } else {
        el.__wfBtnAnim = animate(
          el,
          { y: [0, -1.5, 0], scale: [1, 0.985, 1] },
          { duration: 0.46, delay, easing: [0.16, 1, 0.3, 1], clearOnFinish: true }
        );
      }
    });
  }

  let lastClickWaveAt = 0;
  function spawnClickWave(clientX, clientY) {
    if (typeof document === "undefined" || !document.body || REDUCED_MOTION()) return;
    if (!Number.isFinite(clientX) || !Number.isFinite(clientY)) return;

    const now = Date.now();
    if (now - lastClickWaveAt < 65) return;
    lastClickWaveAt = now;

    const waveEl = document.createElement("span");
    waveEl.className = "wf-click-wave";
    waveEl.setAttribute("aria-hidden", "true");
    waveEl.style.left = `${Math.round(clientX)}px`;
    waveEl.style.top = `${Math.round(clientY)}px`;
    document.body.appendChild(waveEl);

    const anim = animate(
      waveEl,
      { scale: [0.2, 2.1], opacity: [0.34, 0] },
      { duration: 0.60, easing: [0.16, 1, 0.3, 1] }
    );

    const cleanup = () => {
      if (waveEl.parentNode) waveEl.remove();
    };
    if (anim && anim.finished) {
      anim.finished.then(cleanup).catch(cleanup);
    }
    setTimeout(cleanup, 680);
  }

  function triggerSmoothButtonMotion(btn) {
    if (!btn || btn.disabled || btn.dataset.noMotionPress !== undefined) return;
    if (btn.__wfBtnAnim) btn.__wfBtnAnim.cancel();
    btn.__wfBtnAnim = animate(
      btn,
      { y: [0, -1.5, 0], scale: [0.96, 1.02, 1] },
      { duration: 0.44, easing: [0.16, 1, 0.3, 1], clearOnFinish: true }
    );
  }

  function resolveOptionGroup(targetEl) {
    if (!targetEl || !targetEl.closest) return null;

    const groupBtn = targetEl.closest('[role="group"] button');
    if (groupBtn) {
      const container = groupBtn.closest('[role="group"]');
      return { active: groupBtn, items: Array.from(container.querySelectorAll("button")) };
    }

    const slabBtn = targetEl.closest(".fi-slab-btn");
    if (slabBtn) {
      return { active: slabBtn, items: Array.from(document.querySelectorAll(".fi-slab-btn")) };
    }

    const carTab = targetEl.closest('[data-carousel-target="tab"]');
    if (carTab) {
      const root = carTab.closest('[data-controller~="carousel"]') || document;
      return { active: carTab, items: Array.from(root.querySelectorAll('[data-carousel-target="tab"]')) };
    }

    const carDot = targetEl.closest('[data-carousel-target="dot"]');
    if (carDot) {
      const root = carDot.closest('[data-controller~="carousel"]') || document;
      return { active: carDot, items: Array.from(root.querySelectorAll('[data-carousel-target="dot"]')) };
    }

    const navLink = targetEl.closest("aside nav a");
    if (navLink) {
      const nav = navLink.closest("aside nav");
      return { active: navLink, items: Array.from(nav.querySelectorAll("a")) };
    }

    return null;
  }

  function handleInteractionWave(ev, isClick) {
    if (!isClick && ev.button === 0) {
      spawnClickWave(ev.clientX, ev.clientY);
    }

    const group = resolveOptionGroup(ev.target);
    if (group && group.items.length > 1) {
      if (!isClick) {
        group.active.dataset.wfPressedAt = String(Date.now());
        waveGroup(group.items, group.active);
      } else {
        const last = Number(group.active.dataset.wfPressedAt || 0);
        if (Date.now() - last >= 220) {
          waveGroup(group.items, group.active);
        }
      }
      return;
    }

    const btn = ev.target && ev.target.closest && ev.target.closest("button");
    if (!btn) return;

    if (!isClick) {
      btn.dataset.wfPressedAt = String(Date.now());
      triggerSmoothButtonMotion(btn);
    } else {
      const last = Number(btn.dataset.wfPressedAt || 0);
      if (Date.now() - last >= 220) {
        triggerSmoothButtonMotion(btn);
      }
    }
  }

  function initSmoothMotion() {
    if (typeof document === "undefined") return;

    const cards = Array.from(document.querySelectorAll("main .glass-card")).filter(
      (el) => !el.dataset.wfMotionDone && !el.closest("[data-controller~='motion']")
    );

    if (cards.length) {
      cards.forEach((el) => {
        el.dataset.wfMotionDone = "1";
      });
      animate(
        cards,
        { opacity: [0, 1], y: [14, 0] },
        {
          duration: 0.54,
          delay: stagger(0.045),
          easing: [0.16, 1, 0.3, 1],
          clearOnFinish: true
        }
      );
    }

    if (!global.__wfMotionDelegatedBound) {
      global.__wfMotionDelegatedBound = true;

      document.addEventListener("pointerdown", (ev) => handleInteractionWave(ev, false), { passive: true });
      document.addEventListener("click", (ev) => handleInteractionWave(ev, true), { passive: true });
    }
  }

  if (typeof document !== "undefined") {
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", initSmoothMotion);
    } else {
      initSmoothMotion();
    }
    document.addEventListener("turbo:load", initSmoothMotion);
  }

  global.Motion = { animate, stagger, spring, inView, press, wave, waveGroup, spawnClickWave, initSmoothMotion };
})(window);
